function compute(p) {
  var n = Math.max(2, Math.min(4, Math.round(p.n)));
  var w = [];
  for (var i = 0; i < n; i++) {
    var v = (p.w && p.w[i] !== undefined) ? Number(p.w[i]) : 1;
    if (!isFinite(v) || v < 0) v = 0;
    w.push(v);
  }
  var sum = 0;
  for (var j = 0; j < n; j++) sum += w[j];
  var warning = null;
  var probs = [];
  if (sum <= 0) {
    warning = 'All weights are zero, so no distribution exists; showing the uniform distribution instead.';
    for (var k = 0; k < n; k++) probs.push(1 / n);
  } else {
    for (var m = 0; m < n; m++) probs.push(w[m] / sum);
  }
  var contrib = [];
  var surprisal = [];
  var H = 0;
  for (var q = 0; q < n; q++) {
    var pi = probs[q];
    if (pi > 0) {
      var s = -Math.log(pi) / Math.LN2;
      surprisal.push(s);
      var c = pi * s;
      contrib.push(c);
      H += c;
    } else {
      surprisal.push(null);
      contrib.push(0);
    }
  }
  var labels = [];
  for (var r = 0; r < n; r++) labels.push('outcome ' + (r + 1));
  var maxH = Math.log(n) / Math.LN2;
  var uniform = true;
  for (var t = 0; t < n; t++) {
    if (Math.abs(probs[t] - 1 / n) > 1e-9) uniform = false;
  }
  return {
    n: n,
    probs: probs,
    contrib: contrib,
    surprisal: surprisal,
    H: H,
    maxH: maxH,
    uniform: uniform,
    labels: labels,
    warning: warning
  };
}
